mapper.insert:
/* AiConversationMapper.insertConversation */
INSERT INTO ai_conversation (
    owner_user_no, title, mode, context_label, context_data, use_yn,
    created_by, updated_by, created_at, updated_at, last_message_at
) VALUES (
    #{ownerUserNo}, #{title}, #{mode}, #{contextLabel}, #{contextData}, 'Y',
    #{createdBy}, #{updatedBy}, #{createdAt}, #{updatedAt}, #{lastMessageAt}
)

mapper.select:
/* AiConversationMapper.findConversationByIdAndOwner */
SELECT id, owner_user_no, title, mode, context_label, context_data, use_yn,
       created_by, updated_by, created_at, updated_at, last_message_at
FROM ai_conversation
WHERE id = #{id}
  AND owner_user_no = #{ownerUserNo}
  AND use_yn = 'Y'

/* AiConversationMapper.countConversationsByOwner */
SELECT COUNT(1)
FROM ai_conversation
WHERE owner_user_no = #{ownerUserNo}
  AND use_yn = 'Y'

