/* AiConversationMapper.insertMessage */
INSERT INTO ai_message (
    conversation_id, role, content, message_at, created_by, created_at
) VALUES (
    #{conversationId}, #{role}, #{content}, #{messageAt}, #{createdBy}, #{createdAt}
)

mapper.select:
/* AiConversationMapper.findMessagesByConversation */
SELECT id, conversation_id, role, content, message_at, created_by, created_at
FROM ai_message
WHERE conversation_id = #{conversationId}

    AND id < #{beforeMessageId}

ORDER BY id DESC
LIMIT #{limit}

mapper.update:
/* AiConversationMapper.updateConversationLastMessageAt */
UPDATE ai_conversation
SET last_message_at = #{lastMessageAt},
    updated_by = #{updatedBy},
    updated_at = NOW()
WHERE id = #{id}

/* AiConversationMapper.updateConversationTitle */
UPDATE ai_conversation
SET title = #{title},
    updated_by = #{updatedBy},
    updated_at = NOW()
WHERE id = #{id}
